import React, { useState } from 'react';

function App() {
  const [friends, setFriends] = useState([
    { name: 'Sangavi', balance: -70 },
    { name: 'Max', balance: -180 },
    { name: 'Annie', balance: 10 },
    { name: 'Rajeshwari', balance: 1500 }
  ]);
  const selected = "Max"; // static selection

  const [bill, setBill] = useState('');
  const [yourExp, setYourExp] = useState('');
  const [friendExp, setFriendExp] = useState('');

  function splitBill() {
    const total = parseFloat(bill);
    const yours = parseFloat(yourExp);
    const theirs = parseFloat(friendExp);

    if (isNaN(total) || isNaN(yours) || isNaN(theirs)) {
      alert("Please enter valid numbers.");
      return;
    }

    if (yours + theirs !== total || !selected) {
      alert("Your and friend's expenses must add up to the bill.");
      return;
    }

    const youPaidMore = yours - theirs;

    setFriends((prev) =>
      prev.map((f) =>
        f.name === selected
          ? { ...f, balance: f.balance + youPaidMore }
          : f
      )
    );

    setBill('');
    setYourExp('');
    setFriendExp('');
  }

  return (
    <div style={containerStyle}>
      <h1 style={{ textAlign: 'center', color: '#333' }}>
        🍲 Bill Splitter 💸
      </h1>

      <ul style={{ padding: 0 }}>
        {friends.map((f) => (
          <li
            key={f.name}
            style={{
              background: '#fff',
              padding: '10px',
              marginBottom: '10px',
              borderRadius: '5px',
              borderLeft: f.name === selected ? '5px solid #007bff' : '5px solid transparent'
            }}
          >
            <strong>{f.name}</strong>:&nbsp;
            {f.balance < 0
              ? <span style={{ color: 'red' }}>You owe ₹{-f.balance}</span>
              : f.balance > 0
              ? <span style={{ color: 'green' }}>{f.name} owes you ₹{f.balance}</span>
              : <span style={{ color: 'gray' }}>Settled up</span>}
          </li>
        ))}
      </ul>

      <div style={cardStyle}>
        <h2 style={{ color: '#007bff' }}>Split A Bill With {selected}</h2>

        <input
          type="number"
          placeholder="Bill Value (₹)"
          value={bill}
          onChange={e => setBill(e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Your Expense (₹)"
          value={yourExp}
          onChange={e => setYourExp(e.target.value)}
          style={inputStyle}
        />
        <input
          type="number"
          placeholder="Friend's Expense (₹)"
          value={friendExp}
          onChange={e => setFriendExp(e.target.value)}
          style={inputStyle}
        />

        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '10px' }}>
          <button onClick={splitBill} style={buttonStyle}>
            Split Bill
          </button>
        </div>
      </div>
    </div>
  );
}

// 🎨 Styles
const containerStyle = {
  fontFamily: 'Arial, sans-serif',
  maxWidth: '600px',
  margin: 'auto',
  padding: '30px',
  background: '#f7f7f7',
  borderRadius: '10px',
  boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
};

const cardStyle = {
  background: '#fff',
  padding: '20px',
  borderRadius: '8px',
  marginTop: '20px'
};

const inputStyle = {
  display: 'block',
  width: '100%',
  padding: '10px',
  marginBottom: '10px',
  fontSize: '16px',
  borderRadius: '5px',
  border: '1px solid #ccc'
};

const buttonStyle = {
  padding: '10px 30px',
  fontSize: '16px',
  backgroundColor: '#007bff',
  color: '#fff',
  border: 'none',
  borderRadius: '5px',
  cursor: 'pointer'
};

export default App;
